UPDATE users
SET username = #{username}, email = #{email}, phone = #{phone}, tg_username = #{tgUsername}, full_name = #{fullName}, 
    avatar_url = #{avatarUrl}, department_id = #{departmentId}, position = #{position}, employee_id = #{employeeId}, 
    role = #{role}, updated_by = #{updatedBy}, active = #{active}, email_verified = #{emailVerified}, phone_verified = #{phoneVerified}
WHERE id = #{id}

UPDATE users
SET password = #{password}, password_changed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE users
SET last_login_at = #{lastLoginAt}, last_login_ip = #{lastLoginIp}, login_count = login_count + 1, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
